typedef unsigned int size_t;

extern void *StlSmallAlloc(size_t);

template <bool threads, int inst>
class __my_default_alloc_template {
private:
    enum {_ALIGN = 8};
    enum {_MAX_BYTES = 128};
    enum {_NFREELISTS = _MAX_BYTES / _ALIGN};

    static size_t _S_round_up(size_t __bytes)
    {
        return (((__bytes) + _ALIGN - 1) & ~(_ALIGN - 1));
    }

    union _Obj {
        union _Obj *_M_free_list_link;
        char _M_client_data[1];
    };

    static _Obj *_S_free_list[_NFREELISTS];

    static size_t _S_freelist_index(size_t __bytes)
    {
        return (((__bytes) + _ALIGN - 1) / _ALIGN - 1);
    }

    static char *_S_chunk_alloc(size_t __size, int &__nobjs);
    static char *_S_start_free;
    static char *_S_end_free;
    static size_t _S_heap_size;
};

template <bool __threads, int __inst>
char *
__my_default_alloc_template<__threads, __inst>::_S_chunk_alloc(
    size_t __size, int &__nobjs)
{
    char *__result;
    size_t __total_bytes = __size * __nobjs;
    size_t __bytes_left = _S_end_free - _S_start_free;

    if (__bytes_left >= __total_bytes) {
        __result = _S_start_free;
        _S_start_free += __total_bytes;
        return(__result);
    } else if (__bytes_left >= __size) {
        __nobjs = (int)(__bytes_left / __size);
        __total_bytes = __size * __nobjs;
        __result = _S_start_free;
        _S_start_free += __total_bytes;
        return(__result);
    } else {
        size_t __bytes_to_get =
            2 * __total_bytes + _S_round_up(_S_heap_size >> 4);
        if (__bytes_left > 0) {
            _Obj **__my_free_list =
                _S_free_list + _S_freelist_index(__bytes_left);

            ((_Obj *)_S_start_free)->_M_free_list_link = *__my_free_list;
            *__my_free_list = (_Obj *)_S_start_free;
        }
        _S_start_free = (char *)StlSmallAlloc(__bytes_to_get);
        _S_heap_size += __bytes_to_get;
        _S_end_free = _S_start_free + __bytes_to_get;
        return(_S_chunk_alloc(__size, __nobjs));
    }
}

template char *
__my_default_alloc_template<false, 0>::_S_chunk_alloc(size_t, int &);
